discrete MaterialSupplySystem
port:
    event input real StartPrint;
    event input real StopPrint;
    event output real MaterialReady;
state:
    initial state Standby
        when entry() then
            statehold(0);
        end;
        when receive(StartPrint) then
            transition(Feeding);
        end;
    end;

    state Feeding
        when entry() then
            statehold(0);
        end;
        when receive(StopPrint) then
            transition(Standby);
        end;
        when receive(StartPrint) then
            out
                send(MaterialReady, 1);
            transition(Feeding);
        end;
    end;
end;
end;

discrete PrintControlSystem
port:
    event input real ModelLoaded;
    event input real PauseCommand;
    event input real FaultResolved;
    event input real JobCompleted;
    event output real DataProcessed;
    event output real PrintingStarted;
    event output real PrintingPaused;
    event output real PrintingResumed;
state:
    initial state Preparation
        when entry() then
            statehold(0);
        end;
        when receive(ModelLoaded) then
            transition(DataProcessing);
        end;
    end;

    state DataProcessing
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(Printing);
            out
                send(DataProcessed, 1);
        end;
    end;

    state Printing
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(Printing);
            out
                send(PrintingStarted, 1);
        end;
        when receive(PauseCommand) then
            transition(PauseFault);
            out
                send(PrintingPaused, 1);
        end;
        when receive(JobCompleted) then
            transition(Preparation);
        end;
    end;

    state PauseFault
        when entry() then
            statehold(0);
        end;
        when receive(FaultResolved) then
            transition(Printing);
            out
                send(PrintingResumed, 1);
        end;
        when receive(JobCompleted) then
            transition(Preparation);
        end;
    end;
end;
end;

discrete MechanicalMovementSystem
port:
    event input real MoveCommand;
    event input real InterruptCommand;
    event output real MovementComplete;
state:
    initial state Static
        when entry() then
            statehold(0);
        end;
        when receive(MoveCommand) then
            transition(Moving);
        end;
    end;

    state Moving
        when entry() then
            statehold(0);
        end;
        when timeover() then
            transition(Static);
            out
                send(MovementComplete, 1);
        end;
        when receive(InterruptCommand) then
            transition(Static);
        end;
    end;
end;
end;

discrete MonitoringFeedbackSystem
port:
    event input real ThresholdReached;  // Reaching early warning thresholdsBB
    event input real ProblemSolved;  // Measures to address the problemCC
    event input real ManualConfirmation;  // It&#x27;s okay to confirm.DD
    event output real AlertTriggered;  // Alarm trigger.
event output real MonitoringNormal;  // Surveillance is normal.
state:
    initial state Monitoring
        when entry() then
            statehold(0);
        end;
        when receive(ThresholdReached) then
            transition(Alert);
            out
                send(AlertTriggered, 1);  // Send an alarm trigger.
end;
    end;

    state Alert
        when entry() then
            statehold(0);
        end;
        when receive(ProblemSolved) then
            transition(Monitoring);
            out
                send(MonitoringNormal, 1);  // Send a secure signal.
end;
        when receive(ManualConfirmation) then
            transition(Monitoring);
            out
                send(MonitoringNormal, 1);  // Send a secure signal.
end;
    end;
end;
end;

couple PrinterSystem
import architectureModels.MaterialSupplySystem as MaterialSupply;
import architectureModels.PrintControlSystem as PrintControl;
import architectureModels.MechanicalMovementSystem as MechanicalMovement;
import architectureModels.MonitoringFeedbackSystem as MonitoringFeedback;
part:
    MaterialSupply materialSupply;
    PrintControl printControl;
    MechanicalMovement mechanicalMovement;
    MonitoringFeedback monitoringFeedback;
connection:
    connect(materialSupply.MaterialStatus, printControl.StartPrinting);
    connect(printControl.MoveSignal, mechanicalMovement.MoveCommand);
    connect(mechanicalMovement.MovementComplete, monitoringFeedback.MoveFeedback);
    connect(monitoringFeedback.AlertSignal, materialSupply.StopCommand);
    connect(monitoringFeedback.NormalSignal, printControl.PauseCommand);
end;
